select case when credit_limit >= 13200 then 'high' when credit_limit >= 8200 then 'mid' else 'low' end credit_limit_bucket, count(credit_limit) credit_limit_count from customers where signup_date > '2023-04-29' group by case when credit_limit >= 13200 then 'high' when credit_limit >= 8200 then 'mid' else 'low' end having count(credit_limit) >= 4 order by credit_limit_count, credit_limit_bucket limit 3;
